INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM205J4QM', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular prism has a length of $11$, a width of $4$, and a height of $7$. What is the volume of the prism?', NULL, $lyceon_json$[{"key":"A","text":"$44$"},{"key":"B","text":"$77$"},{"key":"C","text":"$308$"},{"key":"D","text":"$358$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a rectangular prism is $V = l \\times w \\times h = 11 \\times 4 \\times 7 = 308$. The distractor $44$ results from multiplying only the length and width ($11 \\times 4$) and omitting the height. The distractor $77$ results from multiplying only the length and height ($11 \\times 7$) and omitting the width. The distractor $358$ results from an arithmetic slip when computing the product of the three dimensions.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM206Y44K', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'The equation $x^2 + y^2 - 14x + 6y + 33 = 0$ represents a circle in the $xy$-plane. What is the radius of this circle?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'B', NULL, E'Rewrite the equation by completing the square. Group the $x$ and $y$ terms: $(x^2 - 14x) + (y^2 + 6y) = -33$. Complete the square for $x$: $x^2 - 14x + 49 = (x - 7)^2$. Complete the square for $y$: $y^2 + 6y + 9 = (y + 3)^2$. Adding $49$ and $9$ to both sides gives $(x - 7)^2 + (y + 3)^2 = -33 + 49 + 9 = 25$. Since the standard form is $(x - h)^2 + (y - k)^2 = r^2$, the radius is $r = \\sqrt{25} = 5$. The distractor $3$ comes from using only the $y$-coordinate of the center, confusing a component of the center with the radius. The distractor $7$ comes from reading the $x$-coordinate of the center as the radius. The distractor $25$ results from reporting $r^2$ instead of $r$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20GZA0V', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'For what value of $k$ does the equation $3(2x + k) = 6x + 9$ have infinitely many solutions?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$3$"},{"key":"C","text":"$6$"},{"key":"D","text":"$-3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing on the left gives $6x + 3k = 6x + 9$. For the equation to be an identity (true for all $x$), the constant terms must be equal: $3k = 9$, so $k = 3$. The value 9 results from failing to divide by 3 and equating $k$ directly to 9. The value 6 reflects a conceptual error about the relationship between coefficients and constants. The value $-3$ results from a sign error when dividing 9 by 3.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21RP11A', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $5(2x^3 - 7x) + 3x$?', NULL, $lyceon_json$[{"key":"A","text":"$10x^3 - 35x + 3x$"},{"key":"B","text":"$10x^3 - 32x$"},{"key":"C","text":"$10x^3 - 38x$"},{"key":"D","text":"$10x^3 + 32x$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distributing the $5$ gives $10x^3 - 35x$, then adding $3x$ yields $10x^3 - 35x + 3x = 10x^3 - 32x$. The distractor $10x^3 - 35x + 3x$ correctly distributes but fails to combine like terms. The distractor $10x^3 - 38x$ adds $-35x$ and $-3x$ instead of $-35x + 3x$. The distractor $10x^3 + 32x$ reverses the sign on the $-35x$ term before combining.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2344HI5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a survey of $200$ households, $74$ own a cat, $53$ own a dog, and $19$ own both a cat and a dog. If a household is selected at random from those that own a cat, what is the probability that the household also owns a dog?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{200}$"},{"key":"B","text":"$\\frac{19}{74}$"},{"key":"C","text":"$\\frac{19}{53}$"},{"key":"D","text":"$\\frac{53}{200}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The conditional probability of owning a dog given that a household owns a cat is $P(\\text{dog} \\mid \\text{cat}) = \\frac{P(\\text{dog and cat})}{P(\\text{cat})} = \\frac{19}{74}$. The answer $\\frac{19}{200}$ uses the total number of households as the denominator rather than restricting to cat owners. The answer $\\frac{19}{53}$ incorrectly uses the number of dog owners as the denominator (computing the probability of cat ownership given dog ownership). The answer $\\frac{53}{200}$ gives the overall probability of owning a dog, ignoring the condition.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23UN6AE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A recipe calls for $\\frac{7}{4}$ cups of sugar for every $\\frac{3}{2}$ cups of butter. How many cups of sugar are needed for $9$ cups of butter? Express your answer as a fraction or decimal.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21/2', ARRAY['21/2', '10.5'], E'The ratio of sugar to butter is $\\frac{7/4}{3/2} = \\frac{7}{4} \\times \\frac{2}{3} = \\frac{14}{12} = \\frac{7}{6}$. For $9$ cups of butter, the amount of sugar is $\\frac{7}{6} \\times 9 = \\frac{63}{6} = \\frac{21}{2} = 10.5$ cups.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2454NC3', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'If $3x + 2y = 19$ and $x - 2y = -7$, what is the value of $x + y$ ?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$7$"},{"key":"C","text":"$8$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding the two equations eliminates $y$: $(3x + 2y) + (x - 2y) = 19 + (-7)$, giving $4x = 12$, so $x = 3$. Substituting into $x - 2y = -7$ gives $3 - 2y = -7$, so $y = 5$. Therefore $x + y = 3 + 5 = 8$. The value 6 results from stopping at $x = 3$ and reporting $2x$. The value 7 comes from an arithmetic slip in solving for $y$. The value 9 arises from setting up the elimination incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24DYNFD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Lines $p$ and $q$ are parallel and are cut by transversal $t$. The angle formed on the upper-left side of the intersection of $t$ and $p$ measures $127°$. What is the measure, in degrees, of the angle formed on the lower-right side of the intersection of $t$ and $q$?', NULL, $lyceon_json$[{"key":"A","text":"$53°$"},{"key":"B","text":"$127°$"},{"key":"C","text":"$63°$"},{"key":"D","text":"$137°$"}]$lyceon_json$::jsonb, 'B', NULL, E'When two parallel lines are cut by a transversal, corresponding angles are congruent. The upper-left angle at the intersection with line $p$ and the upper-left angle at the intersection with line $q$ are corresponding angles and both measure $127°$. The angle on the lower-right side of the intersection with $q$ is vertically opposite to the upper-left angle at that intersection, so it also measures $127°$. The distractor $53°$ comes from computing the supplement $180° - 127°$ and confusing supplementary with corresponding angles. The distractor $63°$ results from an arithmetic error ($180° - 127° = 53°$, then mistakenly subtracting $10°$). The distractor $137°$ adds $10°$ to the correct measure through misreading.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24VKXR6', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $7x^2 - 3x + 4x^2 + 9x - 2$?', NULL, $lyceon_json$[{"key":"A","text":"$11x^2 + 6x - 2$"},{"key":"B","text":"$11x^2 - 12x - 2$"},{"key":"C","text":"$3x^2 + 6x - 2$"},{"key":"D","text":"$11x^2 + 6x + 2$"}]$lyceon_json$::jsonb, 'A', NULL, E'Combining like terms: $7x^2 + 4x^2 = 11x^2$ and $-3x + 9x = 6x$, so the expression simplifies to $11x^2 + 6x - 2$. The distractor $11x^2 - 12x - 2$ results from subtracting $9x$ instead of adding it. The distractor $3x^2 + 6x - 2$ results from subtracting $4x^2$ from $7x^2$ instead of adding. The distractor $11x^2 + 6x + 2$ incorrectly changes the sign of the constant term from $-2$ to $+2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25AAY3Y', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'The solution set of the compound inequality $-3 < \\frac{4x - 7}{3} \\leq 5$ can be written as $a < x \\leq b$. What is the value of $b - a$ ?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'Multiplying all three parts by 3 gives $-9 < 4x - 7 \\leq 15$. Adding 7 to each part yields $-2 < 4x \\leq 22$. Dividing by 4 gives $-\\frac{1}{2} < x \\leq \\frac{11}{2}$. Therefore $a = -\\frac{1}{2}$ and $b = \\frac{11}{2}$, so $b - a = \\frac{11}{2} - \\left(-\\frac{1}{2}\\right) = \\frac{12}{2} = 6$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25UWJR3', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $4(x + 7) = 2(3x - 5)$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$19$"},{"key":"B","text":"$-19$"},{"key":"C","text":"$\\frac{38}{7}$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing on the left gives $4x + 28$ and on the right gives $6x - 10$. Setting them equal: $4x + 28 = 6x - 10$. Subtracting $4x$ from both sides gives $28 = 2x - 10$. Adding 10 to both sides gives $38 = 2x$, so $x = 19$. The value $-19$ comes from a sign error when moving terms across the equation. The value $\\frac{38}{7}$ results from incorrectly combining the $x$-coefficients as $4 + 3 = 7$ instead of $6 - 4 = 2$. The value 9 arises from an arithmetic slip such as computing $28 - 10 = 18$ and dividing by 2.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26RU3M9', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of $x$ satisfies the inequality $7x - 11 > 24$ ?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'D', NULL, E'Adding 11 to both sides gives $7x > 35$, so $x > 5$. Of the choices, only 6 is greater than 5. The value 5 is not a solution because the inequality is strict (not $\\geq$). The values 3 and 4 result from arithmetic errors in isolating $x$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM285F0HS', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What is the sum of all $x$-values that satisfy the system of equations $y = x^2 - 4x + 2$ and $y = x - 2$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$5$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting the two expressions for $y$ equal gives $x^2 - 4x + 2 = x - 2$. Rearranging: $x^2 - 5x + 4 = 0$, which factors as $(x - 4)(x - 1) = 0$, so $x = 4$ or $x = 1$. The sum of all $x$-values is $4 + 1 = 5$. The value 3 results from a sign error when combining like terms, leading to the equation $x^2 - 3x = 0$ with solutions $0$ and $3$. The value 4 comes from finding only the larger solution $x = 4$ and reporting it as the answer instead of summing both solutions. The value 6 comes from confusing the question with the sum $x + y$ for the solution $(4, 2)$ rather than the sum of all $x$-values.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM289PHA8', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ passes through the point $(2, 5)$ and is perpendicular to the line $4x + 7y = 21$. What is the $y$-intercept of line $p$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{2}$"},{"key":"B","text":"$-\\frac{3}{2}$"},{"key":"C","text":"$\\frac{7}{2}$"},{"key":"D","text":"$\\frac{13}{4}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewriting $4x + 7y = 21$ in slope-intercept form gives $y = -\\frac{4}{7}x + 3$, so the slope is $-\\frac{4}{7}$. The perpendicular slope is $\\frac{7}{4}$. Using point-slope form with $(2, 5)$: $y - 5 = \\frac{7}{4}(x - 2)$, which simplifies to $y = \\frac{7}{4}x - \\frac{14}{4} + \\frac{20}{4} = \\frac{7}{4}x + \\frac{3}{2}$. The $y$-intercept is $\\frac{3}{2}$. The value $-\\frac{3}{2}$ results from a sign error when combining $-\\frac{14}{4}$ and $\\frac{20}{4}$. The value $\\frac{7}{2}$ comes from using the original slope $-\\frac{4}{7}$ instead of the perpendicular slope. The value $\\frac{13}{4}$ results from an incorrect point-slope setup, such as using $(2, 5)$ with the wrong slope formula.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28TG1II', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'grid_in', E'The function $f(x) = x^3 - 9x^2 + 23x - 15$ has three integer zeros. What is the product of the two largest zeros?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15', ARRAY['15'], E'Testing integer values: $f(1) = 1 - 9 + 23 - 15 = 0$, so $x = 1$ is a zero. Dividing by $(x - 1)$ gives $x^2 - 8x + 15 = (x - 3)(x - 5)$. So the three zeros are $1$, $3$, and $5$. The two largest are $3$ and $5$, and their product is $3 \\times 5 = 15$. A common error is finding the product of all three zeros ($1 \\times 3 \\times 5 = 15$, which coincidentally equals the same value) or finding the sum of the two largest zeros ($3 + 5 = 8$).', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28THDK1', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'A linear function $f$ has a rate of change of $4$ and $f(3) = 17$. What is $f(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$29$"},{"key":"C","text":"$12$"},{"key":"D","text":"$17$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since the rate of change (slope) is 4, $f(x) = 4x + b$. Substituting $f(3) = 17$: $4(3) + b = 17$, so $12 + b = 17$ and $b = 5$. Therefore $f(0) = 5$. The value 29 results from adding $4(3) = 12$ to 17 instead of subtracting. The value 12 comes from computing $4(3)$ and stopping without finding the $y$-intercept. The value 17 comes from confusing $f(3)$ with $f(0)$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2980QX4', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'grid_in', E'A student has at most $\\$53$ to spend on notebooks and pens. Each notebook costs $\\$7$ and each pen costs $\\$3$. If the student buys 4 notebooks, what is the maximum number of pens the student can buy?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'The total cost constraint is $7(4) + 3p \\leq 53$, which simplifies to $28 + 3p \\leq 53$. Subtracting 28 from both sides gives $3p \\leq 25$, so $p \\leq 8.\\overline{3}$. Since the number of pens must be a whole number, the maximum is 8.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29V0F22', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a right triangle, one of the acute angles measures $29°$ and the side adjacent to that angle has length $17$. Which expression gives the length of the side opposite the $29°$ angle?', NULL, $lyceon_json$[{"key":"A","text":"$17 \\tan(29°)$"},{"key":"B","text":"$17 \\cos(29°)$"},{"key":"C","text":"$17 \\sin(29°)$"},{"key":"D","text":"$\\dfrac{17}{\\tan(29°)}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The tangent of an angle in a right triangle equals the ratio of the opposite side to the adjacent side: $\\tan(29°) = \\frac{\\text{opposite}}{17}$, so the opposite side equals $17 \\tan(29°)$. Using cosine instead of tangent would give the ratio of the adjacent side to the hypotenuse, which does not isolate the opposite side. Using sine would give the ratio of the opposite side to the hypotenuse, but $17$ is the adjacent side, not the hypotenuse. Dividing $17$ by $\\tan(29°)$ inverts the relationship, which would be correct only if $17$ were the opposite side.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AAFDBK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A cylinder has a radius of $5$ and a height of $9$. What is the volume of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$45\\pi$"},{"key":"B","text":"$90\\pi$"},{"key":"C","text":"$225\\pi$"},{"key":"D","text":"$450\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The volume of a cylinder is $V = \\pi r^2 h = \\pi (5)^2 (9) = \\pi (25)(9) = 225\\pi$. The distractor $45\\pi$ comes from using $\\pi r h$ instead of $\\pi r^2 h$, forgetting to square the radius. The distractor $90\\pi$ results from using the lateral surface area formula $2\\pi r h = 2\\pi(5)(9) = 90\\pi$ instead of the volume formula. The distractor $450\\pi$ results from an arithmetic slip of doubling the correct answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ABXNOO', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $\\sqrt{4x + 9} = 7$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'Squaring both sides gives $4x + 9 = 49$. Subtracting 9 from both sides: $4x = 40$. Dividing by 4: $x = 10$. Checking: $\\sqrt{4(10) + 9} = \\sqrt{49} = 7$, which confirms the solution. A common error is forgetting to square the right side, leading to $4x + 9 = 7$ and $x = -\\frac{1}{2}$. Another error is squaring incorrectly to get $4x + 9 = 14$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AZVB0W', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A university researcher surveyed $310$ students who voluntarily signed up for a study. Students who reported sleeping more than $8$ hours per night had higher GPAs on average than students who reported sleeping fewer than $6$ hours. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"There is an association between reported sleep duration and GPA among the students in the study."},{"key":"B","text":"Sleeping more than $8$ hours per night causes higher GPAs for all university students."},{"key":"C","text":"The results can be generalized to all university students because the sample was large."},{"key":"D","text":"If students who sleep fewer than $6$ hours increase their sleep, their GPAs will improve."}]$lyceon_json$::jsonb, 'A', NULL, E'Because this is an observational study (no random assignment of sleep habits) with a voluntary response sample (not a random sample of all university students), the only supported conclusion is an association between reported sleep duration and GPA among the participants. Claiming that more sleep causes higher GPAs requires a controlled experiment with random assignment. Generalizing to all university students requires a random sample of that population; voluntary sign-up introduces self-selection bias regardless of sample size. Predicting that changing sleep habits will raise GPAs assumes a causal relationship that an observational study cannot establish.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BOFSGC', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'The graphs of $y = x^2 + x - 7$ and $y = 3x + 1$ intersect at two points. What is the intersection point where $x > 0$?', NULL, $lyceon_json$[{"key":"A","text":"$(-2, -5)$"},{"key":"B","text":"$(4, 13)$"},{"key":"C","text":"$(4, 9)$"},{"key":"D","text":"$(2, 5)$"}]$lyceon_json$::jsonb, 'B', NULL, E'Setting the equations equal: $x^2 + x - 7 = 3x + 1$, which simplifies to $x^2 - 2x - 8 = 0$. Factoring gives $(x - 4)(x + 2) = 0$, so $x = 4$ or $x = -2$. Since the question requires $x > 0$, only $x = 4$ applies. Substituting into $y = 3(4) + 1 = 13$ gives the intersection point $(4, 13)$. The point $(-2, -5)$ is the other intersection but has $x < 0$. The point $(4, 9)$ uses the correct $x$-value but incorrectly computes $y = 4^2 + 4 - 7 = 13$, not $9$. The point $(2, 5)$ comes from an error in solving the quadratic.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CRG85W', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $DEF$, angle $D$ measures $(2x + 11)°$, angle $E$ measures $(3x - 7)°$, and angle $F$ measures $(x + 38)°$. What is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '23', ARRAY['23'], E'The sum of interior angles in a triangle is $180°$. Setting up the equation: $(2x + 11) + (3x - 7) + (x + 38) = 180$. Combining like terms gives $6x + 42 = 180$. Subtracting $42$ from both sides yields $6x = 138$. Dividing both sides by $6$ gives $x = 23$. To verify: angle $D = 2(23) + 11 = 57°$, angle $E = 3(23) - 7 = 62°$, angle $F = 23 + 38 = 61°$, and $57 + 62 + 61 = 180°$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DBFPEK', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $5x - 3y = 21$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, -7)$"},{"key":"B","text":"$(0, 7)$"},{"key":"C","text":"$(0, \\frac{21}{5})$"},{"key":"D","text":"$(0, 21)$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $x = 0$ in $5x - 3y = 21$ gives $-3y = 21$, so $y = -7$. The $y$-intercept is $(0, -7)$. The point $(0, 7)$ results from dropping the negative sign when dividing 21 by $-3$. The point $(0, \\frac{21}{5})$ comes from incorrectly setting $y = 0$ and solving for $x$, yielding the $x$-intercept instead. The point $(0, 21)$ comes from reading the constant term directly without dividing by the coefficient of $y$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EGBYDW', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What is the value of $x$ that satisfies $3x + 17 = 44$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Subtracting 17 from both sides yields $3x = 27$. Dividing both sides by 3 gives $x = 9$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F2QYLQ', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'For what value of $k$ does the system of equations $kx + 6y = 14$ and $3x + 9y = 30$ have no solution?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$3$"},{"key":"C","text":"$6$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'A system has no solution when the lines are parallel: equal slopes but different intercepts. Writing both equations in slope-intercept form, the second equation gives $y = -\\frac{1}{3}x + \\frac{10}{3}$, so its slope is $-\\frac{1}{3}$. The first equation gives $y = -\\frac{k}{6}x + \\frac{7}{3}$. Setting slopes equal: $-\\frac{k}{6} = -\\frac{1}{3}$, so $k = 2$. The intercepts $\\frac{7}{3} \\neq \\frac{10}{3}$, confirming parallel (no solution). The value 3 confuses the coefficient of $x$ in the second equation with the required ratio. The value 6 comes from matching $y$-coefficients directly without forming the slope ratio. The value 9 results from misreading the problem as asking when the $y$-coefficients match.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F5NRCZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'Which of the following best describes the end behavior of $f(x) = -2x^4 + 5x - 1$?', NULL, $lyceon_json$[{"key":"A","text":"As $x \\to \\infty$, $f(x) \\to \\infty$; as $x \\to -\\infty$, $f(x) \\to \\infty$"},{"key":"B","text":"As $x \\to \\infty$, $f(x) \\to -\\infty$; as $x \\to -\\infty$, $f(x) \\to -\\infty$"},{"key":"C","text":"As $x \\to \\infty$, $f(x) \\to \\infty$; as $x \\to -\\infty$, $f(x) \\to -\\infty$"},{"key":"D","text":"As $x \\to \\infty$, $f(x) \\to -\\infty$; as $x \\to -\\infty$, $f(x) \\to \\infty$"}]$lyceon_json$::jsonb, 'B', NULL, E'The leading term is $-2x^4$. Since the degree is even (4) and the leading coefficient is negative ($-2$), the function goes to $-\\infty$ in both directions. The first option ignores the negative leading coefficient and treats it as a positive even-degree polynomial. The third option describes odd-degree positive leading coefficient behavior. The fourth option describes odd-degree negative leading coefficient behavior.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FB317P', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $XYZ$, the right angle is at vertex $Y$. If $XY = 7$ and $YZ = 24$, what is $\\sin(Z)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7/25', ARRAY['7/25', '0.28', '.28'], E'First, find the hypotenuse $XZ$ using the Pythagorean theorem: $XZ = \\sqrt{7^2 + 24^2} = \\sqrt{49 + 576} = \\sqrt{625} = 25$. The sine of angle $Z$ is the ratio of the side opposite to angle $Z$ divided by the hypotenuse. The side opposite angle $Z$ is $XY = 7$, and the hypotenuse is $XZ = 25$. Therefore, $\\sin(Z) = \\frac{7}{25}$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FN8B9S', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What value of $x$ satisfies $\\frac{5x - 3}{4} = \\frac{x + 9}{2}$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$\\frac{21}{5}$"},{"key":"C","text":"$5$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Multiplying both sides by 4 gives $5x - 3 = 2(x + 9) = 2x + 18$. Subtracting $2x$ from both sides gives $3x - 3 = 18$. Adding 3 to both sides gives $3x = 21$, so $x = 7$. The value $\\frac{21}{5}$ results from correctly finding $3x = 21$ but then dividing by 5 (the coefficient from the numerator) instead of 3. The value 5 comes from an arithmetic slip when combining like terms. The value $-7$ results from a sign error when isolating the variable.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GUKPI9', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{3}{x - 5} + \\frac{7x}{x^2 - 25}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{10x + 15}{x^2 - 25}$"},{"key":"B","text":"$\\frac{10x - 15}{x^2 - 25}$"},{"key":"C","text":"$\\frac{7x + 3}{x^2 - 25}$"},{"key":"D","text":"$\\frac{10x + 15}{x - 5}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Since $x^2 - 25 = (x - 5)(x + 5)$, rewrite $\\frac{3}{x - 5}$ with denominator $x^2 - 25$ by multiplying numerator and denominator by $(x + 5)$: $\\frac{3(x + 5)}{x^2 - 25} = \\frac{3x + 15}{x^2 - 25}$. Adding: $\\frac{3x + 15 + 7x}{x^2 - 25} = \\frac{10x + 15}{x^2 - 25}$. The distractor $\\frac{10x - 15}{x^2 - 25}$ negates the $15$ from the distribution of $3(x+5)$. The distractor $\\frac{7x + 3}{x^2 - 25}$ adds the numerators without converting to a common denominator. The distractor $\\frac{10x + 15}{x - 5}$ uses the wrong denominator, keeping only one factor instead of the full product.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H2KGMN', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A technician charges a flat service fee plus an hourly rate. A 2-hour job costs $\\$190$ and a 5-hour job costs $\\$385$. What is the technician''s hourly rate, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$65$"},{"key":"B","text":"$60$"},{"key":"C","text":"$77$"},{"key":"D","text":"$95$"}]$lyceon_json$::jsonb, 'A', NULL, E'Let the flat fee be $b$ and the hourly rate be $r$. Then $b + 2r = 190$ and $b + 5r = 385$. Subtracting the first equation from the second gives $3r = 195$, so $r = 65$. The hourly rate is $\\$65$. The value 60 comes from an arithmetic slip in dividing 195 by 3. The value 77 results from incorrectly dividing the total cost of the 5-hour job by 5, which ignores the flat fee. The value 95 comes from dividing the 2-hour job cost by 2, giving the average cost per hour rather than the hourly rate alone.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IUPAZK', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'If $5x - 3y = 13$ and $2x + 3y = 22$, what is the value of $xy$ ?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$15$"},{"key":"C","text":"$20$"},{"key":"D","text":"$25$"}]$lyceon_json$::jsonb, 'C', NULL, E'Adding the equations gives $7x = 35$, so $x = 5$. Substituting into $2(5) + 3y = 22$ yields $3y = 12$, so $y = 4$. Therefore $xy = 5 \\cdot 4 = 20$. The value 9 comes from finding $x + y$ instead of the product. The value 15 results from an arithmetic error when solving for $y$. The value 25 arises from computing $x^2$ instead of $xy$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JNJDWJ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'If $9^x - 4 \\cdot 3^x = 21$, what is the value of $3^x$?', NULL, $lyceon_json$[{"key":"A","text":"$-3$"},{"key":"B","text":"$7$"},{"key":"C","text":"$3$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $u = 3^x$. Since $9^x = (3^2)^x = (3^x)^2 = u^2$, the equation becomes $u^2 - 4u - 21 = 0$. Factoring: $(u - 7)(u + 3) = 0$, so $u = 7$ or $u = -3$. Because $3^x > 0$ for all real $x$, the value $u = -3$ is extraneous, leaving $3^x = 7$. The value $-3$ is the extraneous solution rejected because exponential functions are always positive. The value $3$ confuses $3^x$ with the base itself. The value $21$ mistakes the right-hand side of the original equation for the answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JSXSFQ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The exponential function $p(t) = 400 \\cdot (1.03)^t$ models a population after $t$ years. What does the value $1.03$ represent in this context?', NULL, $lyceon_json$[{"key":"A","text":"The population grows by $3\\%$ each year"},{"key":"B","text":"The population grows by $103$ each year"},{"key":"C","text":"The initial population is $1.03$"},{"key":"D","text":"The population triples every year"}]$lyceon_json$::jsonb, 'A', NULL, E'In the exponential model $p(t) = 400 \\cdot (1.03)^t$, the base $1.03$ equals $1 + 0.03$, meaning the population increases by $3\\%$ per year. Interpreting $1.03$ as an additive increase of $103$ confuses exponential with linear growth. Saying the initial population is $1.03$ confuses the base with the initial value, which is $400$. Saying the population triples each year would require a base of $3$, not $1.03$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LJX05K', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $h(x) = (x - 7)^2 + 3$ is obtained by transforming the parent function $f(x) = x^2$. Which statement correctly describes the transformation?', NULL, $lyceon_json$[{"key":"A","text":"A translation 7 units right and 3 units up"},{"key":"B","text":"A translation 7 units left and 3 units up"},{"key":"C","text":"A translation 7 units right and 3 units down"},{"key":"D","text":"A translation 3 units right and 7 units up"}]$lyceon_json$::jsonb, 'A', NULL, E'The form $(x - 7)^2 + 3$ shifts the parent $x^2$ graph 7 units to the right (because of $x - 7$) and 3 units up (because of the $+3$). A translation 7 units left would correspond to $(x + 7)^2$, confusing the sign convention. A translation 3 units down reverses the vertical direction of the shift. Swapping 3 and 7 reverses which number controls the horizontal versus vertical shift.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LP2WFX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $11$. What is the length of an arc that subtends a central angle of $\\dfrac{2\\pi}{7}$ radians?', NULL, $lyceon_json$[{"key":"A","text":"$\\dfrac{11\\pi}{7}$"},{"key":"B","text":"$\\dfrac{22\\pi}{7}$"},{"key":"C","text":"$\\dfrac{121\\pi}{7}$"},{"key":"D","text":"$\\dfrac{2\\pi}{7}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Arc length equals the radius times the central angle in radians: $s = r\\theta = 11 \\cdot \\dfrac{2\\pi}{7} = \\dfrac{22\\pi}{7}$. The value $\\dfrac{11\\pi}{7}$ results from multiplying only by $\\dfrac{\\pi}{7}$ and dropping the factor of $2$. The value $\\dfrac{121\\pi}{7}$ comes from using the area formula $\\dfrac{1}{2}r^2\\theta$ instead of the arc length formula, yielding $\\dfrac{1}{2}(121)\\dfrac{2\\pi}{7}$. The value $\\dfrac{2\\pi}{7}$ simply restates the central angle without multiplying by the radius.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MDRTTT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A factory produces $174$ widgets in $6$ hours. At this constant rate, how many widgets does the factory produce in $11$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$290$"},{"key":"B","text":"$319$"},{"key":"C","text":"$348$"},{"key":"D","text":"$261$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{174}{6} = 29$ widgets per hour. In $11$ hours the factory produces $29 \\times 11 = 319$ widgets. The distractor $290$ results from an arithmetic error multiplying $29 \\times 10$ instead of $29 \\times 11$. The distractor $348$ comes from doubling the original $174$ rather than computing the correct rate. The distractor $261$ results from using $9$ hours instead of $11$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PR83DZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the age (in years) and height (in centimeters) of $37$ saplings. The line of best fit is $h = 4.7a + 12.3$, where $h$ is height and $a$ is age. What is the best interpretation of the slope in this context?', NULL, $lyceon_json$[{"key":"A","text":"For each additional year of age, the predicted height increases by $4.7$ centimeters."},{"key":"B","text":"For each additional centimeter of height, the predicted age increases by $4.7$ years."},{"key":"C","text":"A sapling with an age of $0$ years has a predicted height of $4.7$ centimeters."},{"key":"D","text":"For each additional year of age, the predicted height increases by $12.3$ centimeters."}]$lyceon_json$::jsonb, 'A', NULL, E'In the equation $h = 4.7a + 12.3$, the slope $4.7$ represents the predicted change in height for each one-unit increase in age, meaning each additional year of age corresponds to a predicted increase of $4.7$ centimeters in height. The interpretation that reverses the variables (each centimeter increases age by $4.7$ years) confuses independent and dependent variables. Interpreting $4.7$ as the height at age $0$ confuses the slope with the y-intercept. Interpreting $12.3$ as the per-year increase confuses the intercept with the slope.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PRHE6G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set contains the values $11, 14, 14, 17, 19, 23, 23, 23, 31$. If the value $31$ is removed from the data set, which of the following statements correctly describes the change?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases and the median stays the same."},{"key":"B","text":"The mean decreases and the median decreases."},{"key":"C","text":"The mean stays the same and the median decreases."},{"key":"D","text":"The mean and the median both stay the same."}]$lyceon_json$::jsonb, 'B', NULL, E'With all 9 values, the sum is $11+14+14+17+19+23+23+23+31 = 175$, so the mean is $\\frac{175}{9} \\approx 19.44$ and the median (5th value) is $19$. After removing $31$, the sum is $144$ with $8$ values, giving a mean of $18$. The new median is the average of the 4th and 5th values: $\\frac{17+19}{2} = 18$. Both the mean and the median decrease. Saying the mean decreases but the median stays the same overlooks that removing the largest value shifts the median positions. Saying the mean stays the same ignores the effect of removing a value above the mean. Saying both stay the same misreads the impact of the removal entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PX77AP', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'Which of the following is equivalent to $3(2x - 9) + 4 \\geq 5x - 14$ ?', NULL, $lyceon_json$[{"key":"A","text":"$x \\geq 9$"},{"key":"B","text":"$x \\geq -9$"},{"key":"C","text":"$x \\leq 9$"},{"key":"D","text":"$x \\leq -9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing gives $6x - 27 + 4 \\geq 5x - 14$, which simplifies to $6x - 23 \\geq 5x - 14$. Subtracting $5x$ from both sides yields $x - 23 \\geq -14$. Adding 23 gives $x \\geq 9$. Choosing $x \\leq 9$ reflects a reversal of the inequality direction without justification. The negative answers result from sign errors when combining constants.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PZJ4Q9', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $(3x - 7)(2x + 11)$?', NULL, $lyceon_json$[{"key":"A","text":"$6x^2 + 19x - 77$"},{"key":"B","text":"$6x^2 - 19x - 77$"},{"key":"C","text":"$6x^2 + 19x + 77$"},{"key":"D","text":"$6x^2 - 47x - 77$"}]$lyceon_json$::jsonb, 'A', NULL, E'Using FOIL: $(3x)(2x) = 6x^2$, $(3x)(11) = 33x$, $(-7)(2x) = -14x$, $(-7)(11) = -77$. Combining the middle terms: $33x - 14x = 19x$. The result is $6x^2 + 19x - 77$. The distractor $6x^2 - 19x - 77$ negates the middle term. The distractor $6x^2 + 19x + 77$ incorrectly makes the constant positive. The distractor $6x^2 - 47x - 77$ adds the middle terms as $-33x - 14x = -47x$, reversing the sign of $33x$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q5PDMG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A random sample of $480$ registered voters in a city found that $57\\%$ support a proposed park renovation, with a margin of error of $4.1$ percentage points at a $95\\%$ confidence level. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Between $52.9\\%$ and $61.1\\%$ of all registered voters in the city are likely to support the renovation."},{"key":"B","text":"Exactly $57\\%$ of all registered voters in the city support the renovation."},{"key":"C","text":"Between $52.9\\%$ and $61.1\\%$ of all people in the city support the renovation."},{"key":"D","text":"The survey proves that a majority of registered voters support the renovation."}]$lyceon_json$::jsonb, 'A', NULL, E'The $95\\%$ confidence interval is $57\\% \\pm 4.1\\%$, which gives the interval from $52.9\\%$ to $61.1\\%$. This interval applies to the population from which the sample was drawn: registered voters in the city. Stating exactly $57\\%$ ignores the margin of error inherent in sample-based estimates. Extending the conclusion to all people in the city overgeneralizes beyond the sampled population of registered voters. Claiming the survey proves a majority ignores that the lower bound of the interval ($52.9\\%$) is only slightly above $50\\%$ and that a confidence interval does not constitute proof.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QR1WMR', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'The function $g$ is defined by $g(x) = -5x + 37$. For what value of $x$ does $g(x) = 12$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Setting $g(x) = 12$: $-5x + 37 = 12$. Subtracting 37 from both sides gives $-5x = -25$. Dividing both sides by $-5$ gives $x = 5$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RDURAW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'Let $f(x) = \\frac{2x^2 - 13x - 7}{x - 7}$ for $x \\neq 7$. For what value of $x$ does $f(x) = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{1}{2}$"},{"key":"B","text":"$7$"},{"key":"C","text":"$\\frac{7}{2}$"},{"key":"D","text":"$-7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Factoring the numerator: $2x^2 - 13x - 7 = (2x + 1)(x - 7)$. So $f(x) = \\frac{(2x + 1)(x - 7)}{x - 7} = 2x + 1$ for $x \\neq 7$. Setting $2x + 1 = 0$ gives $x = -\\frac{1}{2}$. The value $x = 7$ makes the original numerator zero but is excluded from the domain ($x \\neq 7$), so it is a removable discontinuity, not a zero. The value $\\frac{7}{2}$ comes from an error in solving $2x - 7 = 0$ instead of $2x + 1 = 0$. The value $-7$ results from a sign error in factoring the numerator.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SPVCR1', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'A line passes through the points $(3, -1)$ and $(7, 11)$. What is the equation of the line in slope-intercept form?', NULL, $lyceon_json$[{"key":"A","text":"$y = 3x + 10$"},{"key":"B","text":"$y = 3x - 10$"},{"key":"C","text":"$y = -3x + 8$"},{"key":"D","text":"$y = 4x - 13$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $\\frac{11 - (-1)}{7 - 3} = \\frac{12}{4} = 3$. Using point $(3, -1)$: $-1 = 3(3) + b$, so $b = -1 - 9 = -10$. The equation is $y = 3x - 10$. The equation $y = 3x + 10$ results from a sign error in computing the $y$-intercept. The equation $y = -3x + 8$ uses a negated slope, indicating a conceptual gap in slope computation. The equation $y = 4x - 13$ comes from an arithmetic slip in computing the slope as $\\frac{12}{3}$ instead of $\\frac{12}{4}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SRITS8', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'grid_in', E'If $\\frac{6x^2 + 17x - 14}{2x + 7} = ax + b$ for all values of $x$ where the expression is defined, what is the value of $b$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-2', ARRAY['-2'], E'Performing polynomial long division of $6x^2 + 17x - 14$ by $2x + 7$: dividing $6x^2$ by $2x$ gives $3x$. Multiplying $3x(2x + 7) = 6x^2 + 21x$. Subtracting from $6x^2 + 17x$ gives $-4x$. Bringing down $-14$ gives $-4x - 14$. Dividing $-4x$ by $2x$ gives $-2$. Multiplying $-2(2x + 7) = -4x - 14$. Subtracting gives remainder $0$. So $a = 3$ and $b = -2$. One can also factor the numerator as $(2x + 7)(3x - 2)$, confirming the quotient is $3x - 2$ and $b = -2$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T0598T', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What is the positive solution of $x^2 - 3x - 28 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$7$"},{"key":"C","text":"$-4$"},{"key":"D","text":"$14$"}]$lyceon_json$::jsonb, 'B', NULL, E'Factoring gives $(x - 7)(x + 4) = 0$, so $x = 7$ or $x = -4$. The positive solution is $7$. The value $4$ comes from dropping the negative sign on the other root. The value $-4$ is the negative root, not the positive one. The value $14$ might arise from doubling the positive root or misapplying the quadratic formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TNTKO9', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The system of equations $y = x^2 - 4x + k$ and $y = 3x - 7$ has exactly one solution. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{21}{4}$"},{"key":"B","text":"$5$"},{"key":"C","text":"$-\\frac{21}{4}$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting the equations equal: $x^2 - 4x + k = 3x - 7$, giving $x^2 - 7x + (k + 7) = 0$. For exactly one solution, the discriminant must equal zero: $(-7)^2 - 4(1)(k + 7) = 0$. This gives $49 - 4k - 28 = 0$, so $21 = 4k$, and $k = \\frac{21}{4}$. The value $5$ comes from rounding or an arithmetic slip in computing $49 - 28$. The value $-\\frac{21}{4}$ results from a sign error when moving terms. The value $7$ comes from using only the constant term from the linear equation without completing the discriminant calculation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UWNZ1C', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'If $g(x) = x^3 - 4$, what is $g(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$5$"},{"key":"C","text":"$31$"},{"key":"D","text":"$-23$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 3$: $g(3) = 3^3 - 4 = 27 - 4 = 23$. The value $5$ results from computing $3^2 - 4 = 5$, using the wrong exponent. The value $31$ comes from computing $3^3 + 4 = 31$, adding instead of subtracting. The value $-23$ results from a sign error, computing $4 - 27$ instead of $27 - 4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W17DMY', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $3x^2 = 75$, what is the positive value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'Dividing both sides by 3 gives $x^2 = 25$. Taking the square root yields $x = \\pm 5$. Since the question asks for the positive value, $x = 5$. A common error is forgetting to divide by 3 first, which would give $x^2 = 75$ and an irrational result. Another error is giving the negative root $-5$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W5104M', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'The equation of a line is $7x - 2y = 28$. What is the $x$-coordinate of the $x$-intercept?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'At the $x$-intercept, $y = 0$. Substituting into $7x - 2(0) = 28$ gives $7x = 28$, so $x = 4$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WVOBN6', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the exterior angle at vertex $R$ measures $139°$. If angle $P$ measures $53°$, what is the measure, in degrees, of angle $Q$?', NULL, $lyceon_json$[{"key":"A","text":"$41°$"},{"key":"B","text":"$86°$"},{"key":"C","text":"$94°$"},{"key":"D","text":"$127°$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the exterior angle theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. So $139° = 53° + \\text{angle } Q$, giving angle $Q = 139° - 53° = 86°$. The distractor $41°$ comes from incorrectly computing $180° - 139°$, confusing the exterior angle with a supplementary relationship to find the wrong interior angle. The distractor $94°$ results from computing $180° - 86°$, finding the supplement of the correct answer. The distractor $127°$ comes from computing $180° - 53°$, applying the supplement to angle $P$ instead of using the exterior angle theorem.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2X0GSF4', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'The expression $\\frac{18x^3 - 27x^2 - 8x + 12}{3x - 2}$ can be written as $ax^2 + bx + c$ for all values of $x$ where the expression is defined. What is the value of $a + b + c$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-5', ARRAY['-5'], E'Perform polynomial long division of $18x^3 - 27x^2 - 8x + 12$ by $3x - 2$. Dividing $18x^3$ by $3x$ gives $6x^2$. Multiplying $6x^2(3x - 2) = 18x^3 - 12x^2$. Subtracting: $-27x^2 - (-12x^2) = -15x^2$. Bring down $-8x$: $-15x^2 - 8x$. Dividing $-15x^2$ by $3x$ gives $-5x$. Multiplying $-5x(3x - 2) = -15x^2 + 10x$. Subtracting: $-8x - 10x = -18x$. Bring down $12$: $-18x + 12$. Dividing $-18x$ by $3x$ gives $-6$. Multiplying $-6(3x - 2) = -18x + 12$. Remainder is $0$. So the quotient is $6x^2 - 5x - 6$, meaning $a = 6$, $b = -5$, $c = -6$. Therefore $a + b + c = 6 + (-5) + (-6) = -5$. Alternatively, $a + b + c$ equals the quotient evaluated at $x = 1$: $\\frac{18 - 27 - 8 + 12}{3 - 2} = \\frac{-5}{1} = -5$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YGE3EG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'Between 2022 and 2023, the number of members at a community center increased from $430$ to $559$. What is the percent increase, rounded to the nearest tenth?', NULL, $lyceon_json$[{"key":"A","text":"$23.0\\%$"},{"key":"B","text":"$30.0\\%$"},{"key":"C","text":"$76.9\\%$"},{"key":"D","text":"$12.9\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The increase is $559 - 430 = 129$ members. The percent increase is $\\frac{129}{430} \\times 100 \\approx 30.0\\%$. The distractor $23.0\\%$ results from dividing $129$ by $559$ (using the new value rather than the original as the base). The distractor $76.9\\%$ comes from computing $\\frac{430}{559}$ instead of the change over the original. The distractor $12.9\\%$ treats the raw increase $129$ as a percentage without dividing by the original.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YRISN6', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $\\frac{4x^2 - 49}{2x + 7}$ for $x \\neq -\\frac{7}{2}$?', NULL, $lyceon_json$[{"key":"A","text":"$2x + 7$"},{"key":"B","text":"$2x - 7$"},{"key":"C","text":"$4x - 7$"},{"key":"D","text":"$2x^2 - 7$"}]$lyceon_json$::jsonb, 'B', NULL, E'Recognizing that $4x^2 - 49 = (2x)^2 - 7^2$ is a difference of squares, it factors as $(2x - 7)(2x + 7)$. Dividing by $2x + 7$ cancels that factor, leaving $2x - 7$. The distractor $2x + 7$ confuses the two factors and selects the denominator instead of the remaining factor. The distractor $4x - 7$ incorrectly takes the square root of only $49$ but not $4x^2$. The distractor $2x^2 - 7$ divides each term of the numerator by $2$ instead of factoring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z5IP5I', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'A carpenter charges a flat consultation fee of 41 dollars plus 13 dollars for each hour of labor. If a customer receives a bill totaling 119 dollars, how many hours of labor did the carpenter perform?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'B', NULL, E'The carpenter charges a flat fee of 41 dollars plus 13 dollars per hour. Setting up the equation $41 + 13h = 119$ and subtracting $41$ from both sides gives $13h = 78$. Dividing both sides by $13$ yields $h = 6$. The carpenter performed 6 hours of labor. The distractor 5 results from an arithmetic slip when dividing $78$ by $13$. The distractor 7 comes from miscalculating the subtraction step as $119 - 41 = 91$ and then dividing $91$ by $13$. The distractor 9 arises from dividing the total bill $119$ by $13$ without first subtracting the flat fee, reflecting an equation setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z81PK1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A laptop originally priced at $\\$1{,}370$ is on sale for $18\\%$ off. What is the sale price of the laptop?', NULL, $lyceon_json$[{"key":"A","text":"$\\$1{,}123.40$"},{"key":"B","text":"$\\$1{,}246.60$"},{"key":"C","text":"$\\$1{,}103.60$"},{"key":"D","text":"$\\$246.60$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discount is $0.18 \\times 1370 = 246.60$, so the sale price is $1370 - 246.60 = 1123.40$. The distractor $\\$1{,}246.60$ results from subtracting only $\\$123.40$ (computing $0.09 \\times 1370$ instead of $0.18 \\times 1370$). The distractor $\\$1{,}103.60$ comes from computing $1370 \\times 0.82$ but making an arithmetic slip (miscomputing $1370 \\times 0.8 = 1096$ and adding $1370 \\times 0.02 = 7.60$ incorrectly). The distractor $\\$246.60$ confuses the discount amount with the sale price.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZE7NU9', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $f$ satisfies $f(2) = 13$ and $f(8) = -11$. What is the value of $x$ when $f(x) = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{21}{4}$"},{"key":"B","text":"$\\frac{13}{4}$"},{"key":"C","text":"$-\\frac{21}{4}$"},{"key":"D","text":"$5$"}]$lyceon_json$::jsonb, 'A', NULL, E'The slope is $\\frac{-11 - 13}{8 - 2} = \\frac{-24}{6} = -4$. Using point $(2, 13)$: $f(x) = -4(x - 2) + 13 = -4x + 8 + 13 = -4x + 21$. Setting $f(x) = 0$: $-4x + 21 = 0$, so $x = \\frac{21}{4}$. The value $\\frac{13}{4}$ results from dividing $f(2) = 13$ by the absolute slope 4 without accounting for the full linear equation. The value $-\\frac{21}{4}$ results from a sign error when solving $-4x + 21 = 0$. The value 5 comes from an arithmetic slip such as rounding $\\frac{21}{4}$ or miscalculating the $y$-intercept.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZOINL9', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'grid_in', E'If $f(x) = 2x^2 - 11x + 5$, what is the sum of the zeros of $f$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11/2', ARRAY['11/2', '5.5'], E'By Vieta''s formulas, for a quadratic $ax^2 + bx + c$, the sum of the zeros is $-\\frac{b}{a} = -\\frac{-11}{2} = \\frac{11}{2}$. Alternatively, factoring or using the quadratic formula yields zeros at $x = 5$ and $x = \\frac{1}{2}$, and their sum is $5 + \\frac{1}{2} = \\frac{11}{2}$. A common error is computing $\\frac{b}{a} = \\frac{-11}{2}$ without the negation, giving $-\\frac{11}{2}$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZWX0JK', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'In the system of equations $7x + 4y = c$ and $3x - 2y = 11$, the solution satisfies $x = 2y - 1$. What is the value of $c$ ?', NULL, $lyceon_json$[{"key":"A","text":"$42$"},{"key":"B","text":"$48$"},{"key":"C","text":"$52$"},{"key":"D","text":"$56$"}]$lyceon_json$::jsonb, 'D', NULL, E'Substituting $x = 2y - 1$ into $3x - 2y = 11$ gives $3(2y - 1) - 2y = 11$, which simplifies to $6y - 3 - 2y = 11$, so $4y = 14$ and $y = \\frac{7}{2}$. Then $x = 2\\left(\\frac{7}{2}\\right) - 1 = 6$. Substituting into the first equation: $c = 7(6) + 4\\left(\\frac{7}{2}\\right) = 42 + 14 = 56$. The value 42 results from computing only $7x$ and omitting the $4y$ term. The value 48 comes from an arithmetic slip in evaluating $4\\left(\\frac{7}{2}\\right)$ as 6. The value 52 arises from incorrectly finding $y = 3$ through a rounding error in the intermediate step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
