INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22P15NA', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Kenji Otsuka studies the symbiotic relationships between cleaner wrasses and larger reef fish. In his observations off the coast of Sulawesi, each cleaner wrasse _______ a specific territory on the reef where client fish line up to have parasites removed.', $lyceon_json$[{"key":"A","text":"maintain"},{"key":"B","text":"have maintained"},{"key":"C","text":"maintaining"},{"key":"D","text":"maintains"}]$lyceon_json$::jsonb, 'D', NULL, E'The subject "each cleaner wrasse" is singular and requires a singular verb form. The option "maintains" correctly provides the third-person singular present tense to agree with the singular subject. The bare plural form "maintain" fails subject-verb agreement because it does not match the singular "each cleaner wrasse." The plural auxiliary "have maintained" also fails subject-verb agreement and shifts to present perfect tense without contextual justification. The participial form "maintaining" cannot serve as the main verb of the clause, creating a sentence fragment.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
