INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23J4WY2', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The textile fragments recovered from a peat bog near Clonycavan, Ireland—which radiocarbon dating has placed at roughly 2,300 years _______ display weaving techniques remarkably similar to those documented in Iron Age settlements across the Baltic coast.', $lyceon_json$[{"key":"A","text":"old,"},{"key":"B","text":"old—"},{"key":"C","text":"old; they"},{"key":"D","text":"old. They"}]$lyceon_json$::jsonb, 'B', NULL, E'The parenthetical "which radiocarbon dating has placed at roughly 2,300 years old" is introduced by an em dash after "Ireland." Standard English requires that paired delimiters match: an em dash must close with an em dash, not a comma or other mark. The closing em dash after "old" correctly completes the parenthetical, allowing the main clause subject "The textile fragments" to reach its verb "display." Using a comma to close an em-dash-opened parenthetical mixes delimiters, violating boundary conventions. Using a semicolon followed by "they" breaks the sentence: the material before the semicolon has no main verb for "The textile fragments" because the unclosed em dash leaves the parenthetical dangling, and the redundant pronoun "they" restarts the clause unnecessarily. Using a period followed by "They" creates the same structural problem, producing a fragment before the period since the subject "The textile fragments" never receives a main verb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW249EXOB', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Urban planner Miroslav Cerny studied pedestrian traffic patterns in eleven mid-sized European cities and found that streets with continuous tree canopy cover attracted 34 percent more foot traffic than comparable streets without canopy cover, even when both types of streets had identical retail density. Cerny attributes this effect primarily to thermal comfort, noting that surface temperatures beneath continuous canopies were on average 7 degrees Celsius lower during summer months. Based on these findings, Cerny concludes that municipalities seeking to increase pedestrian activity on commercial streets should ________', $lyceon_json$[{"key":"A","text":"invest in planting and maintaining continuous tree canopies rather than relying solely on retail incentives to attract foot traffic."},{"key":"B","text":"eliminate all retail establishments from streets that currently lack tree canopy cover."},{"key":"C","text":"discourage pedestrian use of streets that cannot support tree planting due to underground infrastructure."},{"key":"D","text":"prioritize reducing surface temperatures through reflective pavement rather than through tree canopy expansion."}]$lyceon_json$::jsonb, 'A', NULL, E'Cerny''s research links continuous tree canopy cover to increased foot traffic and attributes this to thermal comfort. The logical completion is that municipalities should invest in tree canopies to boost pedestrian activity, rather than relying on retail incentives alone. The suggestion to eliminate retail from canopy-free streets vastly overstates the findings; Cerny shows canopy increases traffic, not that retail-only streets should be abandoned. Discouraging pedestrian use of streets without trees goes far beyond Cerny''s conclusion, which is about attracting more pedestrians, not deterring them. Prioritizing reflective pavement over trees contradicts Cerny''s specific attribution of the effect to tree canopy cover, not to alternative cooling methods.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24E163Z', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'The fruit fly Drosophila melanogaster has long served as a model organism in genetics research, but a 2019 study by entomologist Priya Raghavan drew attention to an overlooked aspect of the insect''s biology: its capacity for rudimentary social learning. Raghavan''s team demonstrated that female fruit flies that observed other females rejecting a particular male were significantly more likely to reject that same male themselves. The finding was striking because social learning had previously been documented almost exclusively in vertebrates, and it suggested that even organisms with brains containing roughly 100,000 neurons can acquire behavioral information from conspecifics.', $lyceon_json$[{"key":"A","text":"Raghavan's research revealed that fruit flies can engage in a form of social learning, a capacity once thought to be limited to vertebrates."},{"key":"B","text":"Fruit flies are the most important model organism for genetics research because their brains contain approximately 100,000 neurons."},{"key":"C","text":"The rejection of particular mates by female fruit flies is driven entirely by instinct rather than by observation of other flies."},{"key":"D","text":"Entomologists before Raghavan had already established that invertebrates frequently display complex social learning behaviors."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Raghavan''s finding that fruit flies exhibit social learning, a behavior previously associated almost exclusively with vertebrates. The option stating that fruit flies are the most important model organism distorts a detail: the passage says they have long served as a model organism, not that they are the most important one, and it conflates the neuron count with the reason for importance. The option claiming mate rejection is driven entirely by instinct directly contradicts the passage''s central finding. The option suggesting entomologists had already established invertebrate social learning reverses the passage''s point that the finding was striking precisely because such learning was previously documented almost exclusively in vertebrates.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24KCY8Y', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which finding, if true, would most directly weaken the claim made by Okonkwo''s team?', E'Archaeologist Chinwe Okonkwo and her team have argued that the abandonment of the Nri-Igbo settlement complex around 1450 CE was precipitated by a prolonged regional drought that decimated crop yields and made sustained habitation untenable. Their claim rests partly on pollen-core samples from a nearby lake that show a marked decline in cultivated grain pollen beginning around 1430 CE. Critics, however, have noted that the pollen record could reflect a deliberate shift in agricultural strategy rather than crop failure.', $lyceon_json$[{"key":"A","text":"Oral traditions recorded in the seventeenth century describe a period of severe water scarcity in the region during the mid-fifteenth century."},{"key":"B","text":"Strontium isotope analysis of skeletal remains from the settlement indicates that most residents relocated to a wetter river-valley region after 1440 CE."},{"key":"C","text":"Sediment cores from the same lake show that annual rainfall levels between 1400 and 1500 CE were consistent with the long-term regional average."},{"key":"D","text":"Archaeological excavations at a neighboring site reveal that its population also declined sharply around 1460 CE."}]$lyceon_json$::jsonb, 'C', NULL, E'Okonkwo''s team claims a prolonged drought caused the settlement''s abandonment. If sediment cores from the same lake show rainfall was normal during the relevant period, that directly undermines the drought hypothesis. Oral traditions describing water scarcity would support rather than weaken the drought claim. Strontium isotope evidence of relocation to a wetter area is consistent with drought-driven migration, so it would also tend to support the claim. A neighboring site''s population declining around the same time could have multiple causes and does not specifically challenge the drought explanation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW259KF2J', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing about the physicist Chien-Shiung Wu for a history of science journal. The student wants to present a contrast between Wu''s experimental contribution and the recognition she received. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26GFD9L', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text?', E'Coral reefs occupy less than one percent of the ocean floor, yet they support roughly one quarter of all known marine species. [underlined] Marine biologist Kendra Osei has documented over 340 distinct species within a single reef system off the coast of Belize. [/underlined] Her census, conducted over seven years of fieldwork, revealed that even small patches of reef can harbor extraordinary biodiversity.', $lyceon_json$[{"key":"A","text":"It provides a specific example illustrating the preceding claim."},{"key":"B","text":"It introduces a counterargument to an established theory about the geographic distribution of marine life across different ocean habitats."},{"key":"C","text":"It raises a question that the remainder of the passage will attempt to resolve through further evidence."},{"key":"D","text":"It shifts the passage's focus away from biodiversity and toward a discussion of research methodology."}]$lyceon_json$::jsonb, 'A', NULL, E'The preceding sentence makes the general claim that reefs support roughly one quarter of all marine species. The underlined sentence then cites Osei''s documentation of 340 species within a single reef, which serves as a concrete example illustrating that general claim. The option about introducing a counterargument is wrong because Osei''s finding supports rather than challenges the claim about reef biodiversity. The option about raising a question is wrong because the underlined sentence is a declarative statement of findings, not an inquiry. The option about shifting to research methodology is wrong because the sentence''s emphasis is on the number of species found, not on how the research was conducted.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27X7FG6', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction to a presentation about urban beekeeping. The student wants to emphasize the environmental benefits of the practice. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28NQ6PU', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'The Iberian lynx was once considered the most endangered cat species on Earth, with fewer than 100 individuals remaining in the wild by 2002. Conservation programs in Spain and Portugal focused on habitat restoration and captive breeding. ________ the population has rebounded to over 1,100 individuals as of 2023.', $lyceon_json$[{"key":"A","text":"As a result,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"On the other hand, despite these concerns,"},{"key":"D","text":"For instance,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes conservation efforts (habitat restoration and captive breeding) and then states the population rebounded. The relationship is cause and effect, so the transition indicating a result is correct. The contrast transition implies an opposing idea, which contradicts the logical flow. The concessive transition suggesting concerns introduces information not present in the passage. The example transition implies what follows illustrates the prior point, but the rebound is a consequence, not an example.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW292SZVT', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'When the Portuguese explorer Fernão Mendes Pinto published his memoir Peregrinação in 1614, European readers dismissed it as outlandish fabrication. Pinto claimed to have visited Japan, sailed with Chinese pirates, and been shipwrecked seventeen times — adventures so extreme that his surname became a Portuguese synonym for liar. Modern historians, however, have corroborated many of Pinto''s accounts. Ship manifests, Jesuit correspondence, and Japanese temple records independently confirm several episodes he described, suggesting that Pinto''s reputation for dishonesty was itself largely a myth.', $lyceon_json$[{"key":"A","text":"It presents a historical figure's poor reputation and then offers evidence complicating it."},{"key":"B","text":"It compares two competing scholarly interpretations of a literary text and ultimately rejects both of those interpretations as oversimplified."},{"key":"C","text":"It describes a series of geographical discoveries and evaluates which ones had the greatest lasting cultural impact on European societies."},{"key":"D","text":"It chronicles the stages of an explorer's career in strictly chronological order from earliest to latest voyage across multiple continents."}]$lyceon_json$::jsonb, 'A', NULL, E'The text first establishes that Pinto was dismissed as a fabricator and even became synonymous with dishonesty, then pivots with "however" to present corroborating evidence from ship manifests and other records, complicating the original poor reputation. The option about comparing two competing interpretations and rejecting both is wrong because the text ultimately favors the revisionist view supported by modern evidence rather than rejecting it. The option about evaluating geographical discoveries for cultural impact is wrong because the text focuses on Pinto''s credibility rather than ranking the significance of any discoveries. The option about chronicling career stages in strict chronological order is wrong because the text is organized around a reputational contrast, not a linear timeline of voyages.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW298RVSK', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'As used in the text, what does the word "purchase" most nearly mean?', E'On the steep granite face of El Faro, even experienced climbers struggled to find purchase. The rock had been polished by centuries of wind and rain, leaving surfaces so smooth that conventional handholds were nearly impossible to establish without specialized friction pads.', $lyceon_json$[{"key":"A","text":"a secure grip or foothold on a surface"},{"key":"B","text":"an acquisition obtained through a commercial transaction"},{"key":"C","text":"a mechanical lever used to multiply applied physical force"},{"key":"D","text":"a formal requisition submitted through official procurement channels"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes climbers on a polished granite face who cannot establish handholds, so "purchase" refers to a secure grip or foothold on a surface. The option about a commercial transaction invokes the most common meaning of "purchase" but has no relevance to the physical challenge of climbing a rock face. The option about a mechanical lever describes a different technical sense of "purchase" from engineering, but the passage specifies the difficulty of gripping smooth rock rather than applying leverage. The option about formal requisition through procurement channels applies a bureaucratic meaning entirely disconnected from the physical context of rock climbing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2A4WCMO', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Soil ecologist Tamara Voskresenskaya has challenged the prevailing assumption that mycorrhizal networks — the underground fungal filaments connecting plant root systems — function primarily as mutualistic resource-sharing pathways. Analyzing isotope-tracer data from 47 temperate-forest plots in the Ural Mountains, Voskresenskaya found that carbon transferred through mycorrhizal connections flowed disproportionately toward already-dominant trees, effectively reinforcing existing competitive hierarchies rather than leveling them. She cautions, however, that her results do not negate mutualism entirely: under drought stress, the same networks redistributed water toward smaller saplings, suggesting that the networks'' ecological role is context-dependent rather than uniformly cooperative or competitive.', $lyceon_json$[{"key":"A","text":"Voskresenskaya's research suggests that mycorrhizal networks function in ways that are more complex and context-dependent than the prevailing mutualistic model implies."},{"key":"B","text":"Mycorrhizal networks are exclusively competitive structures that benefit large trees at the expense of smaller plants in all environmental conditions."},{"key":"C","text":"Voskresenskaya's isotope-tracer methodology was flawed because it failed to account for water redistribution during periods of drought stress."},{"key":"D","text":"The mutualistic model of mycorrhizal networks has been definitively confirmed by recent research conducted in temperate forests."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Voskresenskaya''s finding that mycorrhizal networks can reinforce competitive hierarchies under normal conditions yet redistribute resources cooperatively under drought, concluding that the networks'' role is context-dependent. The option calling the networks exclusively competitive ignores the passage''s explicit caveat about water redistribution to saplings during drought, overstating the competitive finding. The option claiming the methodology was flawed misreads the passage: Voskresenskaya herself reported the drought-stress finding, meaning it was part of her data rather than an oversight. The option stating the mutualistic model has been definitively confirmed directly contradicts the passage, which describes a challenge to that model.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AHG5CQ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the geothermal vents discovered by oceanographer Rajesh Kulkarni in the Mariana Trough release water heated to over 310 degrees _______ the organisms thriving near these vents have evolved proteins that remain stable at temperatures far exceeding those tolerated by most known extremophiles.', $lyceon_json$[{"key":"A","text":"Celsius;"},{"key":"B","text":"Celsius."},{"key":"C","text":"Celsius,"},{"key":"D","text":"Celsius:"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence opens with the subordinating conjunction "Although," which makes the first clause dependent. A comma after "Celsius" correctly marks the boundary between the introductory subordinate clause and the main clause that follows. A semicolon is incorrect because semicolons join two independent clauses, and the "Although" clause is dependent. A period after "Celsius" creates a sentence fragment, since a clause beginning with "Although" cannot stand alone as a complete sentence. A colon is incorrect because colons require an independent clause before them, and the subordinate clause does not qualify.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DJ114L', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Haenyeo, female divers of Jeju Island in South Korea, have harvested abalone and sea urchins from the ocean floor for centuries. Despite the physical demands of their work, many of these women continue diving well into their seventies. A recent documentary about the Haenyeo _______ international attention to their declining numbers, as fewer young women choose to carry on the tradition.', $lyceon_json$[{"key":"A","text":"have been drawing"},{"key":"B","text":"has drawn"},{"key":"C","text":"are drawing and have drawn"},{"key":"D","text":"have drawn considerably more"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the blank is "A recent documentary," which is singular and requires a singular auxiliary verb. The option "has drawn" correctly uses the third-person singular present perfect to agree with the singular subject. The option "have been drawing" uses the plural auxiliary "have," which does not agree with the singular subject "documentary." The option "are drawing and have drawn" compounds two verb phrases both using plural auxiliaries, each failing subject-verb agreement. The option "have drawn considerably more" also uses the plural auxiliary "have," violating agreement with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F6TCIB', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary about the archaeological site of Gobekli Tepe. The student wants to highlight a finding that challenges a widely held assumption about early human societies. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GDBYGB', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Historian Elif Batuman has argued that the 19th-century Russian novel served as a form of philosophical inquiry, not merely as entertainment. She notes that Dostoevsky embedded competing moral frameworks within dialogue rather than resolving them through authorial commentary. ________ Batuman suggests that this technique anticipated 20th-century existentialist philosophy by several decades, a claim that some scholars dispute on chronological grounds.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"For example,"},{"key":"C","text":"Building on this observation,"},{"key":"D","text":"In contrast to this general assessment,"}]$lyceon_json$::jsonb, 'C', NULL, E'The second sentence describes Dostoevsky''s technique of embedding competing moral frameworks, and the final sentence extends that observation into a broader claim about anticipating existentialist philosophy. The relationship is one of building upon the preceding point to develop a larger argument. The concession transition wrongly implies the broader claim contradicts the observation about Dostoevsky''s technique. The example transition implies the broader claim merely illustrates the previous point, but it actually advances the argument further. The contrast transition suggests a reversal of direction, yet the claim about anticipating existentialism extends rather than opposes the idea of novels as philosophical inquiry.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M0PQKC', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists Kenji Arakawa and Sofia Lindqvist have hypothesized that the sharp decline in Pacific herring populations observed in the Salish Sea between 2011 and 2017 was driven primarily by a reduction in the availability of calanoid copepods, the herring''s chief prey during early life stages. Alternative explanations include increased predation by harbor seals and disruption from underwater noise pollution generated by commercial shipping traffic.', $lyceon_json$[{"key":"A","text":"Herring populations in Norwegian fjords, where calanoid copepod densities remained stable, did not decline during the same period."},{"key":"B","text":"Harbor seal populations in the Salish Sea tripled between 2005 and 2017."},{"key":"C","text":"Commercial shipping traffic in the Salish Sea increased steadily from 2008 to 2020."},{"key":"D","text":"Pacific herring in the Salish Sea shifted to deeper spawning sites after 2014."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers'' hypothesis attributes the herring decline specifically to reduced copepod availability. The finding that herring populations did not decline in a region where copepod densities stayed stable directly supports the proposed link between copepod availability and herring population health. The finding about harbor seal populations tripling would support the alternative predation explanation, not the copepod hypothesis. The finding about increased shipping traffic would support the noise-pollution alternative. The finding about deeper spawning sites is tangentially related to herring behavior but does not directly connect copepod availability to population decline.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MYNOBT', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Neuroscientist Yael Berman-Kishoni has investigated how bilingual speakers process syntactic ambiguity differently from monolingual speakers. In her 2022 study, she presented participants with garden-path sentences — sentences whose initial parsing leads to an incorrect interpretation that must be revised upon encountering later words. Monolingual English speakers exhibited a strong N400 event-related potential (a neural marker of semantic surprise) when they reached the disambiguating word, indicating that they had committed to the initial, incorrect parse. Bilingual speakers of English and Hebrew, however, showed a significantly attenuated N400 response at the same point, even though their ultimate comprehension accuracy was equivalent. Berman-Kishoni interprets this as evidence that ________', $lyceon_json$[{"key":"A","text":"bilingual speakers maintain multiple syntactic parses simultaneously rather than committing fully to a single interpretation, reducing the neural cost of revision when the initial parse proves incorrect."},{"key":"B","text":"monolingual speakers possess a more efficient sentence-processing system because they commit to interpretations more quickly than bilingual speakers do."},{"key":"C","text":"the N400 response is not a reliable indicator of syntactic processing difficulty and should be replaced by other neural measures in future research."},{"key":"D","text":"bilingual speakers achieve higher comprehension accuracy than monolingual speakers because they process garden-path sentences without any initial misinterpretation."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage reports that bilingual speakers showed a weaker N400 (less semantic surprise) at the disambiguating word yet achieved equivalent comprehension. The most logical inference is that they were not fully committed to the initial incorrect parse, meaning they maintained competing interpretations simultaneously, which reduced revision cost. The option about monolinguals having a more efficient system mischaracterizes the data: committing to one parse faster led to greater surprise and revision cost, which is not straightforwardly more efficient. The option dismissing the N400 as unreliable contradicts the passage''s use of the N400 as the basis for its conclusions; the researcher interprets the measure, not discards it. The option claiming bilingual speakers had higher accuracy contradicts the passage, which explicitly states comprehension accuracy was equivalent between groups.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OHHAYV', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Glaciologist Amara Osei-Bonsu, whose fieldwork in the Rwenzori Mountains has reshaped scientific understanding of equatorial ice loss, argues that satellite imaging alone cannot capture the rapid changes occurring at high altitudes. In a 2023 paper, Osei-Bonsu contended that researchers who _______ on remote sensing data without supplementing it with ground-level measurements risk producing models that significantly underestimate the rate of glacial retreat.', $lyceon_json$[{"key":"A","text":"has relied exclusively"},{"key":"B","text":"rely exclusively"},{"key":"C","text":"relying exclusively"},{"key":"D","text":"relies, exclusively,"}]$lyceon_json$::jsonb, 'B', NULL, E'The relative clause "who _______" modifies "researchers," a plural noun, and serves as the subject of the verb "risk" later in the sentence. The option "rely exclusively" provides the correct plural present-tense form to agree with the plural antecedent "researchers." The option "has relied exclusively" uses the singular auxiliary "has," which does not agree with the plural "researchers." The participial form "relying exclusively" cannot serve as the finite verb of the relative clause introduced by "who," leaving the clause without a main verb. The option "relies, exclusively," uses a singular verb form that fails to agree with "researchers" and incorrectly sets off "exclusively" with commas as though it were a parenthetical, when it is an integral adverb modifying the verb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OT9ZLI', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'As used in the text, what does the word "volatile" most nearly mean?', E'During the 1840s, the price of whale oil became increasingly volatile. Merchants who had previously relied on steady annual contracts found themselves unable to predict costs from one month to the next, and several prominent trading houses in New Bedford collapsed under the strain of these unpredictable swings.', $lyceon_json$[{"key":"A","text":"dangerous and physically explosive"},{"key":"B","text":"subject to rapid, unpredictable change"},{"key":"C","text":"deliberately hostile and aggressive toward others"},{"key":"D","text":"chemically unstable under normal conditions"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes whale oil prices that merchants could not predict from month to month, with swings causing trading houses to collapse. This context establishes that "volatile" refers to something subject to rapid, unpredictable change. The option describing something dangerous and physically explosive applies a literal chemistry meaning unrelated to price behavior. The option about hostility and aggression describes interpersonal behavior, not market fluctuations. The option about chemical instability applies to laboratory conditions, not economic patterns.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
