INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RNCGD4', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In the early twentieth century, the physicist Lise Meitner collaborated with chemist Otto Hahn on experiments involving the bombardment of uranium with neutrons. When Hahn''s chemical analyses in 1938 revealed that barium, an element far lighter than uranium, was among the products, Meitner and her nephew Otto Frisch proposed the theoretical explanation: the uranium nucleus had split into roughly equal fragments, releasing enormous energy as predicted by Einstein''s mass-energy equivalence. Though the 1944 Nobel Prize in Chemistry was awarded solely to Hahn for the discovery, historians of science have increasingly argued that Meitner''s exclusion reflected institutional biases rather than a fair assessment of intellectual contribution, as her physical insight was indispensable to understanding the results Hahn had obtained.', $lyceon_json$[{"key":"A","text":"Meitner's theoretical work was essential to explaining nuclear fission, and her exclusion from the Nobel Prize is now widely viewed as a consequence of institutional bias."},{"key":"B","text":"Hahn's chemical experiments were unnecessary because Meitner had already predicted theoretically that uranium nuclei could split."},{"key":"C","text":"The discovery of nuclear fission was entirely the product of Meitner's calculations, with Hahn contributing only routine laboratory assistance."},{"key":"D","text":"Einstein's mass-energy equivalence was first experimentally verified by Meitner and Frisch through their bombardment of uranium with neutrons."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a collaboration in which Hahn''s chemical analyses and Meitner''s theoretical explanation were both vital, then notes that historians now view Meitner''s Nobel exclusion as reflecting institutional bias. The option claiming Hahn''s experiments were unnecessary contradicts the passage, which states his analyses revealed the unexpected products that needed explaining. The option asserting the discovery was entirely Meitner''s overstates her role; the passage emphasizes collaboration and says her insight was indispensable to understanding Hahn''s results, not that she did everything. The option about Einstein''s equation being first verified by Meitner and Frisch misreads the passage: Meitner invoked mass-energy equivalence in her explanation, but the passage does not say this constituted the first experimental verification of it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TXSB7V', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the University of Gothenburg have found that certain deep-sea sponges can filter microplastic particles from surrounding water. The sponges accumulate these particles in their tissues without apparent harm to themselves. ________ the researchers caution that relying on sponges as a large-scale filtration system would be impractical, since the organisms grow extremely slowly and cannot be cultivated in sufficient quantities.', $lyceon_json$[{"key":"A","text":"Similarly, in a related line of inquiry,"},{"key":"B","text":"However,"},{"key":"C","text":"In addition,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first two sentences present a seemingly positive finding (sponges filter microplastics without harm), but the final sentence introduces a limitation (impracticality of large-scale use). This shift from positive to cautionary requires a contrast transition. The similarity transition wrongly implies the caution extends a parallel finding rather than countering the optimistic implication. The additive transition fails to signal the shift in direction from positive to cautionary. The consequence transition implies the caution follows logically from the filtering ability, but the caution actually opposes the optimism the filtering ability might inspire.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WXVTFW', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'As used in the text, what does the word "tempered" most nearly mean?', E'The ceramicist Luisa Garzon was known for bold, unrestrained glazework in her early career. After a residency in Okinawa, however, her approach became tempered: she began favoring muted earth tones and deliberate negative space, producing vessels that conveyed stillness rather than exuberance.', $lyceon_json$[{"key":"A","text":"heated and then rapidly cooled for increased hardness"},{"key":"B","text":"made more moderate and restrained in character"},{"key":"C","text":"provoked into irritation or open frustration"},{"key":"D","text":"blended together into an entirely new compound"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage contrasts Garzon''s earlier "bold, unrestrained" style with her later preference for "muted earth tones" and "stillness," indicating that "tempered" means made more moderate and restrained. The option about heating and cooling describes a metallurgical process, which does not fit the context of an artist''s evolving aesthetic. The option about provocation into irritation invokes the phrase "losing one''s temper," but the passage describes a calm, deliberate shift rather than anger. The option about blending into a new compound describes a chemical process irrelevant to the description of stylistic moderation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XON2PA', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the purpose of the second paragraph in the overall text?', E'Phenological records — observations of seasonal biological events such as first bloom dates or bird migration arrivals — have been kept by amateur naturalists since at least the eighteenth century. The Marsham family of Norfolk, England, maintained an unbroken phenological diary from 1736 to 1947, tracking twenty-seven indicators including the first leafing of oak trees and the arrival of swallows.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XPYTP2', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which quotation from the study would, if accurate, most effectively support the student''s argument?', E'A student writing a research paper argues that exposure to polyphonic music during early childhood enhances spatial-temporal reasoning skills more effectively than exposure to monophonic melodies. The student has found a 2021 longitudinal study by cognitive psychologist Elara Vasquez that tracked 283 children across seven years.', $lyceon_json$[{"key":"A","text":"\"Children in the polyphonic-exposure group scored, on average, 17 percentile points higher on spatial-temporal tasks at age nine than those in the monophonic group, even after controlling for parental education, household income, and hours of general music instruction.\""},{"key":"B","text":"\"Both the polyphonic and monophonic groups outperformed a no-music control group on spatial-temporal measures, confirming that musical exposure of any kind confers cognitive benefits relative to silence.\""},{"key":"C","text":"\"Parental engagement during music-listening sessions was the strongest single predictor of spatial-temporal gains, regardless of whether the music was polyphonic or monophonic.\""},{"key":"D","text":"\"The polyphonic-exposure group showed elevated cortisol levels during testing sessions, which may have independently influenced performance on timed spatial reasoning tasks.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The student argues that polyphonic music enhances spatial-temporal reasoning more effectively than monophonic melodies. The quotation reporting a 17-percentile-point advantage for the polyphonic group, with confounding variables controlled, directly supports that comparative claim. The quotation about both groups outperforming a no-music control shows that any music helps relative to none but does not establish that polyphonic exposure is superior to monophonic, so it is only partially relevant. The quotation identifying parental engagement as the strongest predictor actually undermines the student''s focus on musical texture. The quotation about elevated cortisol introduces a confounding variable suggesting the polyphonic group''s results may have been influenced by stress rather than by the music itself, which weakens rather than supports the argument.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XXX50L', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Entomologist Darya Kolesnikova has spent over a decade studying the navigational abilities of monarch butterflies. Her research, conducted at a field station in rural _______ that these insects rely on a combination of a time-compensated sun compass and a magnetic sense to orient themselves during migration.', $lyceon_json$[{"key":"A","text":"Manitoba, demonstrates"},{"key":"B","text":"Manitoba. Demonstrates"},{"key":"C","text":"Manitoba demonstrates,"},{"key":"D","text":"Manitoba, it demonstrates"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence requires a comma after the location to close the parenthetical phrase "conducted at a field station in rural Manitoba" and then continues with the main verb "demonstrates." Using a period after Manitoba creates two fragments: the first sentence lacks a main verb for the subject "Her research," and the second begins with "Demonstrates" but has no subject. Placing the comma after "demonstrates" rather than after "Manitoba" fails to close the parenthetical and incorrectly separates the verb from its object clause. Inserting "it" after a comma creates a comma splice with a redundant pronoun, since "research" is already the subject of the clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZT3FG6', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Historian Amara Diallo has documented that during the 1870s, communities of formerly enslaved people in coastal South Carolina developed intricate tidal-irrigation systems for rice cultivation that differed markedly from the antebellum methods imposed by plantation owners. Whereas the antebellum approach relied on permanent earthen dikes that required constant maintenance and restricted natural water flow, the post-emancipation systems used movable wooden sluice gates that could be adjusted to mimic the estuary''s natural tidal rhythms. Diallo notes that these innovations resulted in comparable rice yields while dramatically reducing labor inputs, which suggests that ________', $lyceon_json$[{"key":"A","text":"the agricultural knowledge of formerly enslaved communities included sophisticated hydraulic engineering principles that had been suppressed under the plantation system."},{"key":"B","text":"antebellum plantation owners had deliberately chosen the most labor-efficient rice cultivation methods available at the time."},{"key":"C","text":"the post-emancipation tidal-irrigation systems were direct replicas of irrigation techniques used in West African rice-growing regions."},{"key":"D","text":"permanent earthen dikes produced significantly higher rice yields than movable sluice gates under all conditions."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that formerly enslaved communities independently developed more labor-efficient irrigation methods yielding comparable harvests. This implies they possessed sophisticated engineering knowledge that had not been applied under the plantation system. The option about plantation owners choosing the most labor-efficient methods contradicts the passage, which shows the antebellum approach was more labor-intensive than the post-emancipation one. The option about West African replication introduces a specific historical claim not supported by the passage; while plausible as outside knowledge, the passage provides no evidence for it. The option claiming dikes produced higher yields contradicts the passage''s statement that the newer systems achieved comparable yields with less labor.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-10-04"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-10-04","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
